svg.script:
// Data
const data = [45, 22, 68, 12, 89, 34, 56, 78, 5, 91, 28, 63];
let originalData = [...data];
let currentData = [...data];
let isRunning = false;
let speed = 300;
let steps = 0;
let abortSort = false;

const barWidth = 50;
const barGap = 8;
const maxHeight = 200;
const maxValue = Math.max(...data);

// Create bars
function createBars() {
  const container = document.getElementById('bars-container');
  container.innerHTML = '';

  currentData.forEach((value, index) => {
    const height = (value / maxValue) * maxHeight;
    const x = index * (barWidth + barGap);
    const y = maxHeight - height;

    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('class', 'bar-group');
    g.setAttribute('data-index', index);

    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rect.setAttribute('x', x);
    rect.setAttribute('y', y);
    rect.setAttribute('width', barWidth);
    rect.setAttribute('height', height);
    rect.setAttribute('fill', '#3498db');
    rect.setAttribute('rx', 4);
    rect.setAttribute('id', 'bar-' + index);

    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('x', x + barWidth / 2);
    text.setAttribute('y', maxHeight + 20);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('fill', '#eee');
    text.setAttribute('class', 'label');
    text.textContent = value;

    g.appendChild(rect);
    g.appendChild(text);
    container.appendChild(g);
  });
}

function updateBarColor(index, color) {
  const bar = document.getElementById('bar-' + index);
  if (bar) bar.setAttribute('fill', color);
}

function updateStatus(text) {
  document.getElementById('status').textContent = text;
}

function updateStepCount() {
  document.getElementById('step-count').textContent = 'Steps: ' + steps;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function bubbleSort() {
  const n = currentData.length;

  for (let i = 0; i < n - 1 && !abortSort; i++) {
    for (let j = 0; j < n - i - 1 && !abortSort; j++) {
      // Highlight comparing bars
      updateBarColor(j, '#e74c3c');
      updateBarColor(j + 1, '#e74c3c');
      updateStatus('Comparing ' + currentData[j] + ' and ' + currentData[j + 1]);
      await sleep(speed);

      if (currentData[j] > currentData[j + 1]) {
        // Swap
        updateStatus(currentData[j] + ' > ' + currentData[j + 1] + ' → Swapping!');
        await sleep(speed / 2);

        const temp = currentData[j];
        currentData[j] = currentData[j + 1];
        currentData[j + 1] = temp;
        steps++;
        updateStepCount();

        // Re-render bars
        createBars();

        // Keep highlight on swapped positions
        updateBarColor(j, '#f39c12');
        updateBarColor(j + 1, '#f39c12');
      } else {
        updateStatus(currentData[j] + ' ≤ ' + currentData[j + 1] + ' → No swap needed');
      }

      await sleep(speed / 2);

      // Reset colors
      updateBarColor(j, '#3498db');
      updateBarColor(j + 1, '#3498db');
    }

    // Mark as sorted
    updateBarColor(n - i - 1, '#2ecc71');
  }

  if (!abortSort) {
    updateBarColor(0, '#2ecc71');
    updateStatus('Sorting complete! ✓');
    isRunning = false;
  }
}

// Controls
document.getElementById('btn-start').addEventListener('click', async () => {
  if (!isRunning) {
    isRunning = true;
    abortSort = false;
    if (steps === 0) {
      await bubbleSort();
    } else {
      // Reset and start fresh
      reset();
      await sleep(100);
      await bubbleSort();
    }
  }
});

function reset() {
  abortSort = true;
  isRunning = false;
  currentData = [...originalData];
  steps = 0;
  updateStepCount();
  updateStatus('Click \'Start\' to begin sorting');
  createBars();
}

document.getElementById('btn-reset').addEventListener('click', reset);

document.getElementById('btn-slow').addEventListener('click', () => {
  speed = 500;
  updateStatus('Speed set to Slow');
});

document.getElementById('btn-fast').addEventListener('click', () => {
  speed = 150;
  updateStatus('Speed set to Fast');
});

// Initialize
createBars();
